CustomField.formula:
IF(
  AND(Account.F3_Posicion_Global__c  >= 5000, Account.F3_Posicion_Global__c   <=  100000), "Low",
  IF(
      AND(Account.F3_Posicion_Global__c  >= 100001, Account.F3_Posicion_Global__c   <=  500000), "Medium",
      IF(
         Account.F3_Posicion_Global__c  >= 500001, "High", ""
      )
    )
  )
